    "h_statements": [
      {
        "code": "H225",
        "text": "인화성 액체 및 증기",
        "line": "p1:L22"
      },
      {
        "code": "H335",
        "text": "호흡기계 자극을 일으킬 수 있음",
        "line": "p1:L23"
      },
      {
        "code": "H336",
        "text": "졸음 또는 현기증을 일으킬 수 있음",
        "line": "p1:L24"
      }
    ],
    "p_statements": [
      {
        "code": "P210",
        "type": "예방",
        "text": "열·스파크·화염·고열로부터 멀리하시오 - 금연",
        "line": "p1:L27"
      },
      {
        "code": "P233",
        "type": "예방",
        "text": "용기를 단단히 밀폐하시오.",
        "line": "p1:L28"
      },
      {
        "code": "P240",
        "type": "예방",
        "text": "용기·수용설비를 접지·접합시키시오.",
        "line": "p1:L29"
      },
      {
        "code": "P241",
        "type": "예방",
        "text": "폭발 방지용 전기·환기·조명 등의 장비를 사용하시오.",
        "line": "p1:L30"
      },
      {
        "code": "P242",
        "type": "예방",
        "text": "스파크가 발생하지 않는 도구를 사용하시오",
        "line": "p1:L31"
      },
      {
        "code": "P243",
        "type": "예방",
        "text": "정전기 방지 조치를 취하시오.",
        "line": "p1:L32"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "증기 스프레이의 흡입을 피하시오.",
        "line": "p1:L33"
      },
      {
        "code": "P271",
        "type": "예방",
        "text": "옥외 또는 환기가 잘 되는 곳에서만 취급하시오.",
        "line": "p1:L34"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑·보호의·보안경 및 안면보호구를 착용하시오.",
        "line": "p1:L35"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부(또는 머리카락)에 묻으면 오염된 모든 의복은 벗으시오. 피부를 물로 씻으시오/샤워하시오.",
        "line": "p1:L37"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p1:L39"
      },
      {
        "code": "P312",
        "type": "대응",
        "text": "불편함을 느끼면 의료기관(의사)의 진찰을 받으시오.",
        "line": "p2:L3"
      },
      {
        "code": "P370+P378",
        "type": "대응",
        "text": "화재 시 불을 끄기 위해 미세한 분무 또는 내알코올성 포말을 사용하시오.",
        "line": "p2:L4"
      },
      {
        "code": "P403+P233",
        "type": "저장",
        "text": "용기는 환기가 잘 되는 곳에 단단히 밀폐하여 저장하시오.",
        "line": "p2:L6"
      },
      {
        "code": "P403+P235",
        "type": "저장",
        "text": "환기가 잘 되는 곳에 보관하고 저온으로 유지하시오.",
        "line": "p2:L7"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "밀봉하여 저장하시오.",
        "line": "p2:L8"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "재활용 또는 소각하여 내용물·용기를 폐기하시오.",
        "line": "p2:L10"
      }
    ],
